using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Threading;using System.Windows.Forms;
namespace GearLab {
 public static class WorkspaceTests {
  static int checks;static void Check(bool v,string text){checks++;if(!v)throw new Exception(text);}static void Wait(Func<bool> f,string text){var clock=System.Diagnostics.Stopwatch.StartNew();while(!f()&&clock.Elapsed.TotalSeconds<120){Application.DoEvents();Thread.Sleep(15);}Check(f(),text);}
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var doc=new CADDocument{Name="Контур для выдавливания"};var sketch=new CADFeature{Kind="sketch",Name="Прямоугольник",Sketch=new CADSketch()};sketch.Sketch.Entities.Add(new CADEntity{Kind="rectangle",Width="60",Height="40",Points=new System.Collections.Generic.List<double[]>{new[]{0.0,0.0}}});doc.Features.Add(sketch);var cad=new CADStudioForm(doc,null);using(var shell=new WorkspaceShell(cad)){shell.Show();Wait(()=>cad.State!=null&&cad.Scene.Ready,"embedded CAD starts and initializes scene");Check(!cad.TopLevel&&shell.TopLevel,"one top level window");Check(cad.State.Bodies.Count==0&&cad.Scene.HasConstruction,"finished sketch visible without solids");Check(cad.Scene.Camera.Camera.Position!=new System.Windows.Media.Media3D.Point3D(),"empty scene camera initialized");cad.Scene.SavePng(Path.Combine(folder,"sketch-3d.png"),1000,700);string saved=doc.Serialize();cad.Scene.Camera.Yaw=.3;cad.Scene.Camera.Update();shell.Navigate("robot");var robot=(RobotDesignerForm)shell.Pages.SelectedTab.Tag;Wait(()=>robot.Scene.Ready&&robot.Build!=null,"robot opens inside tab");Check(!robot.TopLevel&&Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"robot navigation opens no extra top level windows");Check(robot.Build.Model.Valid,"default robot geometry valid");Check(!robot.Scene.MoveParts,"robot defaults to camera navigation");shell.Navigate("cad");Check(ReferenceEquals(shell.Pages.SelectedTab.Tag,cad),"return to same CAD document");Check(cad.Document.Serialize()==saved&&Math.Abs(cad.Scene.Camera.Yaw-.3)<1e-8,"document and camera preserved across workspaces");shell.Navigate("robot");Check(shell.Pages.TabCount==2,"repeated navigation reuses core tabs");robot.SetStage(3);int builds=robot.Scene.MeshBuildCount;var joint=robot.Document.Joints[0];double previous=joint.Position;string toolId=robot.Document.Joints.Last().Id;var tip=robot.Build.Current[toolId].Tip;robot.SetJointPose(joint.Id,Math.Min(joint.Maximum,previous+20));Check(robot.Scene.MeshBuildCount==builds,"manual joint pose reuses geometry");Check((robot.Build.Current[toolId].Tip-tip).Length>.01,"manual angle changes displayed kinematics");Check(Math.Abs(robot.Analysis.Joints[0].Required-RobotSolver.Solve(robot.Build).Joints[0].Required)<1e-6,"manual pose updates static loads");robot.SetJointPose(joint.Id,10000);Check(joint.Position==joint.Maximum,"manual pose respects joint limit");robot.SetJointPose(joint.Id,previous);robot.SetStage(0);using(var bitmap=new Bitmap(shell.Width,shell.Height)){shell.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(folder,"workspace-robot.png"));}shell.Navigate("mechanism");Wait(()=>((MechanismForm)shell.Pages.SelectedTab.Tag).Scene.Ready,"mechanism starts in same window");Check(Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"mechanism also embedded");shell.Navigate("cad");var empty=new CADStudioForm();shell.AddDocument(empty,null);Wait(()=>empty.State!=null&&empty.Scene.Ready,"empty CAD scene ready");Check(empty.State.Bodies.Count==0&&!empty.Scene.HasConstruction,"empty model has working scene without fake geometry");using(var bitmap=new Bitmap(shell.Width,shell.Height)){shell.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(folder,"workspace-empty.png"));}var suppressed=doc.Clone();suppressed.Features[0].Suppressed=true;var off=new CADStudioForm(suppressed,null);shell.AddDocument(off,null);Wait(()=>off.State!=null&&off.Scene.Ready,"suppressed sketch does not remove 3D scene");Check(!off.Scene.HasConstruction,"suppressed sketch not falsely displayed");shell.ApproveTestClose();shell.Close();}File.WriteAllText(Path.Combine(folder,"workspace-results.txt"),"PASS "+checks+" workspace assertions: one-window navigation, sketch display, empty scene, state preservation, manual robot pose, limits and loads.",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"workspace-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
